def _rext(src, n, want_max):
    from collections import deque
    m = len(src)
    out = [None] * m
    dq = deque()
    for i in range(m):
        x = src[i]
        if want_max:
            while dq and src[dq[-1]] <= x:
                dq.pop()
        else:
            while dq and src[dq[-1]] >= x:
                dq.pop()
        dq.append(i)
        if dq[0] <= i - n:
            dq.popleft()
        if i >= n - 1:
            out[i] = src[dq[0]]
    return out


def _sr(xs):
    n = len(xs)
    if n < 2:
        return None
    mu = sum(xs) / n
    va = sum((x - mu) ** 2 for x in xs) / (n - 1)
    if va <= 0.0:
        return None
    return mu / (va ** 0.5)


def family_init(ctx):
    """Base rule + a walk-forward CPCV gate computed only on closed trades."""
    from itertools import combinations
    import random
    bars = ctx.bars
    m = len(bars)
    h = [float(b["h"]) for b in bars]
    l = [float(b["l"]) for b in bars]
    c = [float(b["c"]) for b in bars]

    cands = (10, 20, 40)
    H = max(2, int(ctx.p.hold))
    N = max(3, int(ctx.p.n_groups))
    K = 2
    win = max(400, int(ctx.p.win))
    refit = max(50, int(ctx.p.refit))
    emb = max(0, int(round(float(ctx.p.emb_frac) * win)))
    purge = max(1, int(round(float(ctx.p.purge_mult) * H)))
    min_sr = float(ctx.p.min_sr)
    p05_sr = float(ctx.p.p05_sr)
    nb = max(20, int(ctx.p.n_boot))
    minp = max(2, int(ctx.p.min_path))

    # base rule, one series of fires per candidate lookback
    fires = {}
    for n in cands:
        up = _rext(h, n, True)
        dn = _rext(l, n, False)
        f = [0] * m
        for i in range(n, m):
            u = up[i - 1]
            d = dn[i - 1]
            if u is None or d is None:
                continue
            if c[i] > u:
                f[i] = 1
            elif c[i] < d:
                f[i] = -1
        fires[n] = f

    # the H-bar realised return of a fire at bar j -- KNOWN ONLY at bar j+H,
    # and only ever read below with j <= i - H - 1
    fwd = [None] * m
    for j in range(m - H):
        if c[j] > 0.0:
            fwd[j] = (c[j + H] - c[j]) / c[j]

    armed = [False] * m
    pick = [cands[1]] * m

    def _score(n, js):
        out = []
        f = fires[n]
        for j in js:
            s = f[j]
            if s and fwd[j] is not None:
                out.append(s * fwd[j])
        return out

    rng = random.Random(12345)
    start = win + H + 2
    i = start
    while i < m:
        hi_j = i - H - 1
        lo_j = hi_j - win
        if lo_j < 0:
            lo_j = 0
        span = hi_j - lo_j
        ok = False
        sel = cands[1]
        if span >= N * 20:
            gsz = span // N
            gb = [(lo_j + g * gsz,
                   lo_j + (g + 1) * gsz if g < N - 1 else hi_j)
                  for g in range(N)]
            paths = {}
            splits = list(combinations(range(N), K))
            votes = {}
            for si, test in enumerate(splits):
                tset = []
                for g in test:
                    tset.append(gb[g])
                train = []
                for g in range(N):
                    if g in test:
                        continue
                    a, b = gb[g]
                    for j in range(a, b):
                        bad = False
                        for (ta, tb) in tset:
                            # purge: label window [j, j+H] touching a test block
                            if j + purge >= ta and j <= tb + purge:
                                bad = True
                                break
                            # embargo: the bars just after a test block
                            if tb <= j < tb + emb:
                                bad = True
                                break
                        if not bad:
                            train.append(j)
                if len(train) < 40:
                    continue
                best = None
                bestn = None
                for n in cands:
                    r = _score(n, train)
                    if len(r) < 10:
                        continue
                    mu = sum(r) / len(r)
                    if best is None or mu > best:
                        best = mu
                        bestn = n
                if bestn is None:
                    continue
                votes[bestn] = votes.get(bestn, 0) + 1
                for g in test:
                    a, b = gb[g]
                    r = _score(bestn, range(a, b))
                    paths.setdefault(g, []).append(r)
            if votes:
                sel = max(sorted(votes), key=lambda k: votes[k])
            nph = N - 1
            srs = []
            good = len(paths) == N
            if good:
                for pth in range(nph):
                    acc = []
                    for g in range(N):
                        occ = paths.get(g) or []
                        if pth < len(occ):
                            acc.extend(occ[pth])
                    if len(acc) < minp:
                        good = False
                        break
                    s = _sr(acc)
                    if s is None:
                        good = False
                        break
                    srs.append(s)
            if good and srs:
                if min(srs) > min_sr:
                    means = []
                    ns = len(srs)
                    for _ in range(nb):
                        means.append(sum(srs[rng.randrange(ns)]
                                         for _ in range(ns)) / ns)
                    means.sort()
                    k = int(0.05 * len(means))
                    if means[k] > p05_sr:
                        ok = True
        for j in range(i, min(m, i + refit)):
            armed[j] = ok
            pick[j] = sel
        i += refit

    ctx._armed = armed
    ctx._pick = pick
    ctx._fires = fires


def signal(ctx, i):
    if not ctx._armed[i]:
        return 0
    f = ctx._fires.get(ctx._pick[i])
    if f is None:
        return 0
    return int(f[i])
